class Solution:
    def supersequences(self, words: List[str]) -> List[List[int]]:
        chars = sorted(set(''.join(words)))
        idx = {c: i for i, c in enumerate(chars)}
        k = len(chars); full = (1 << k) - 1
        inm = [0] * k
        for w in words:
            inm[idx[w[1]]] |= 1 << idx[w[0]]
        g = [False] * (1 << k); g[0] = True
        for S in range(1, full + 1):
            for v in range(k):
                if (S >> v) & 1 and not (inm[v] & S) and g[S ^ (1 << v)]:
                    g[S] = True
                    break
        best = min(bin(D).count('1') for D in range(full + 1) if g[full ^ D])
        res = []
        for D in range(full + 1):
            if g[full ^ D] and bin(D).count('1') == best:
                f = [0] * 26
                for i, c in enumerate(chars):
                    f[ord(c) - 97] = 2 if (D >> i) & 1 else 1
                res.append(f)
        return res

