class Solution {
public:
    vector<vector<int>> supersequences(vector<string>& words) {
        bool pres[26] = {};
        for (auto& w : words) { pres[w[0]-'a'] = true; pres[w[1]-'a'] = true; }
        int id[26]; fill(id, id+26, -1); vector<int> ch;
        for (int c = 0; c < 26; c++) if (pres[c]) { id[c] = ch.size(); ch.push_back(c); }
        int k = ch.size(), full = (1 << k) - 1;
        vector<int> inm(k, 0);
        for (auto& w : words) inm[id[w[1]-'a']] |= 1 << id[w[0]-'a'];
        vector<char> g(1 << k, 0); g[0] = 1;
        for (int S = 1; S <= full; S++)
            for (int v = 0; v < k; v++)
                if (((S >> v) & 1) && !(inm[v] & S) && g[S ^ (1 << v)]) { g[S] = 1; break; }
        int best = k + 1;
        for (int D = 0; D <= full; D++)
            if (g[full ^ D]) best = min(best, __builtin_popcount(D));
        vector<vector<int>> res;
        for (int D = 0; D <= full; D++)
            if (g[full ^ D] && __builtin_popcount(D) == best) {
                vector<int> f(26, 0);
                for (int i = 0; i < k; i++) f[ch[i]-'a'] = (D >> i & 1) ? 2 : 1;
                res.push_back(f);
            }
        return res;
    }
};

