class Solution {
    public List<List<Integer>> supersequences(String[] words) {
        boolean[] pres = new boolean[26];
        for (String w : words) { pres[w.charAt(0)-'a'] = true; pres[w.charAt(1)-'a'] = true; }
        int[] id = new int[26]; Arrays.fill(id, -1); List<Integer> ch = new ArrayList<>();
        for (int c = 0; c < 26; c++) if (pres[c]) { id[c] = ch.size(); ch.add(c); }
        int k = ch.size(), full = (1 << k) - 1;
        int[] inm = new int[k];
        for (String w : words) inm[id[w.charAt(1)-'a']] |= 1 << id[w.charAt(0)-'a'];
        boolean[] g = new boolean[1 << k]; g[0] = true;
        for (int S = 1; S <= full; S++)
            for (int v = 0; v < k; v++)
                if (((S >> v) & 1) != 0 && (inm[v] & S) == 0 && g[S ^ (1 << v)]) { g[S] = true; break; }
        int best = k + 1;
        for (int D = 0; D <= full; D++) if (g[full ^ D]) best = Math.min(best, Integer.bitCount(D));
        List<List<Integer>> res = new ArrayList<>();
        for (int D = 0; D <= full; D++)
            if (g[full ^ D] && Integer.bitCount(D) == best) {
                List<Integer> f = new ArrayList<>(Collections.nCopies(26, 0));
                for (int i = 0; i < k; i++) f.set(ch.get(i), ((D >> i) & 1) != 0 ? 2 : 1);
                res.add(f);
            }
        return res;
    }
}

