var supersequences = function(words) {
    const pres = new Set();
    for (const w of words) { pres.add(w[0]); pres.add(w[1]); }
    const chars = [...pres].sort();
    const idx = {}; chars.forEach((c, i) => idx[c] = i);
    const k = chars.length, full = (1 << k) - 1;
    const inm = new Array(k).fill(0);
    for (const w of words) inm[idx[w[1]]] |= 1 << idx[w[0]];
    const g = new Uint8Array(1 << k); g[0] = 1;
    const pc = x => { let c = 0; while (x) { c += x & 1; x >>= 1; } return c; };
    for (let S = 1; S <= full; S++)
        for (let v = 0; v < k; v++)
            if ((S >> v & 1) && !(inm[v] & S) && g[S ^ (1 << v)]) { g[S] = 1; break; }
    let best = k + 1;
    for (let D = 0; D <= full; D++) if (g[full ^ D]) best = Math.min(best, pc(D));
    const res = [];
    for (let D = 0; D <= full; D++)
        if (g[full ^ D] && pc(D) === best) {
            const f = new Array(26).fill(0);
            for (let i = 0; i < k; i++) f[chars[i].charCodeAt(0) - 97] = (D >> i & 1) ? 2 : 1;
            res.push(f);
        }
    return res;
};
